class TokenService:
    """Handles API token generation and validation.

    Token format: base_payload.timestamp.signature
    Signature = HMAC-SHA256(base_payload + '.' + timestamp, secret)
    """

    def __init__(self, secret_key):
        self._secret = secret_key

    def _sanitize_payload(self, payload_str):
        """Sanitize payload string - reject non-ASCII to prevent unicode attacks."""
        if not payload_str.isascii():
            return None
        return payload_str

    def generate_token(self, username, role):
        """Generate a signed API token for the given user."""
        timestamp = str(int(time.time()))
        base_payload = f"{username}:{role}"

        sign_input = f"{base_payload}.{timestamp}"

        signature = hmac.new(
            self._secret if isinstance(self._secret, bytes) else self._secret.encode(),
            sign_input.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()

        return f"{base_payload}.{timestamp}.{signature}"

    def validate_token(self, token):
        """Validate token signature and expiry. Returns (username, role) or None."""
        parts = token.rsplit('.', 2)
        if len(parts) != 3:
            return None

        base_payload, timestamp, provided_sig = parts

        # Reject non-ASCII payloads entirely
        if not base_payload.isascii():
            return None

        # Check expiry
        try:
            token_time = int(timestamp)
        except ValueError:
            return None

        if time.time() - token_time > app.config['TOKEN_EXPIRY']:
            return None

        # Recompute signature - use raw payload (already verified ASCII-only)
        sign_input = f"{base_payload}.{timestamp}"

        expected_sig = hmac.new(
            self._secret if isinstance(self._secret, bytes) else self._secret.encode(),
            sign_input.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()

        # Constant-time comparison to prevent timing attacks
        if not hmac.compare_digest(provided_sig, expected_sig):
            return None

        # Extract username and role from payload
        payload_parts = base_payload.split(':')
        if len(payload_parts) != 2:
            return None

        username, role = payload_parts[0], payload_parts[1]

        # Validate role is a known value
        if role not in AccessControl.ROLE_HIERARCHY:
            return None

        return username, role


class AccessControl:
    """Role-based access control with classification levels."""

    ROLE_HIERARCHY = {
        'admin': 3,
        'analyst': 2,
        'viewer': 1
    }

    CLASSIFICATION_LEVELS = {
        'public': 1,
        'internal': 2,
        'confidential': 3,
        'top_secret': 4
    }

    ROLE_CLEARANCE = {
        'admin': 'top_secret',
        'analyst': 'internal',
        'viewer': 'public'
    }

    @classmethod
    def check_role(cls, user_role, required_role):
        """Check if user_role meets or exceeds required_role."""
        user_level = cls.ROLE_HIERARCHY.get(user_role, 0)
        required_level = cls.ROLE_HIERARCHY.get(required_role, 99)
        return user_level >= required_level

    @classmethod
    def can_access_document(cls, user_role, doc_classification):
        """Check if user's clearance allows access to document classification."""
        clearance = cls.ROLE_CLEARANCE.get(user_role, 'public')
        user_clearance_level = cls.CLASSIFICATION_LEVELS.get(clearance, 0)
        doc_level = cls.CLASSIFICATION_LEVELS.get(doc_classification, 99)
        return user_clearance_level >= doc_level


token_service = TokenService(app.config['SECRET_KEY'])


def require_auth(required_role='viewer'):
    """Decorator that validates token and checks role."""
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            auth_header = request.headers.get('Authorization', '')
            if not auth_header.startswith('Bearer '):
                abort(401)

            token = auth_header[7:]
            result = token_service.validate_token(token)

            if result is None:
                abort(401)

            username, role = result

            if not AccessControl.check_role(role, required_role):
                abort(403)

            request.current_user = username
            request.current_role = role
            return f(*args, **kwargs)
        return decorated
    return decorator


@app.route('/api/auth/token', methods=['POST'])
def get_token():
    """Authenticate with API key and get a signed token."""
    data = request.get_json()
    if not data or 'username' not in data or 'api_key' not in data:
        abort(400)

    username = data['username']
    api_key = data['api_key']

    # Reject non-ASCII usernames
    if not username.isascii() or not re.match(r'^[a-zA-Z0-9_-]+$', username):
        abort(400)

    # Validate credentials
    key_hash = hashlib.sha256(api_key.encode('utf-8')).hexdigest()
    row = DB.execute(
        "SELECT role, api_key_hash FROM users WHERE username = ?",
        (username,)
    ).fetchone()

    if row is None or not hmac.compare_digest(row[1], key_hash):
        abort(401)

    role = row[0]
    token = token_service.generate_token(username, role)
    return jsonify({'token': token})


@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@require_auth('viewer')
def get_document(doc_id):
    """Get a document if user has sufficient clearance."""
    row = DB.execute(
        "SELECT title, content, classification FROM documents WHERE id = ?",
        (doc_id,)
    ).fetchone()

    if row is None:
        abort(404)

    title, content, classification = row

    if not AccessControl.can_access_document(request.current_role, classification):
        abort(403)

    return jsonify({'title': title, 'content': content, 'classification': classification})


@app.route('/api/admin/users', methods=['POST'])
@require_auth('admin')
def create_user():
    """Admin-only: create a new user."""
    data = request.get_json()
    if not data or 'username' not in data or 'role' not in data or 'api_key' not in data:
        abort(400)

    # Validate role
    if data['role'] not in AccessControl.ROLE_HIERARCHY:
        abort(400)

    # Validate username format
    if not data['username'].isascii() or not re.match(r'^[a-zA-Z0-9_-]+$', data['username']):
        abort(400)

    key_hash = hashlib.sha256(data['api_key'].encode('utf-8')).hexdigest()
    try:
        DB.execute(
            "INSERT INTO users (username, role, api_key_hash) VALUES (?, ?, ?)",
            (data['username'], data['role'], key_hash)
        )
        DB.commit()
    except sqlite3.IntegrityError:
        abort(409)

    return jsonify({'status': 'created'}), 201


@app.route('/api/admin/documents/<int:doc_id>', methods=['DELETE'])
@require_auth('admin')
def delete_document(doc_id):
    """Admin-only: delete a document."""
    result = DB.execute("DELETE FROM documents WHERE id = ?", (doc_id,))
    DB.commit()
    if result.rowcount == 0:
        abort(404)
    return jsonify({'status': 'deleted'})


if __name__ == '__main__':
    app.run(debug=False)
